INSERT INTO `mdl_aicode` VALUES (1,2,'Quiz 1','',1,'','javascript','','','','',0,'training','',1774969410,1774969410),(2,2,'­ƒÆ╗ Latihan 1: Hello World JavaScript','<p>Latihan pertama: tulis program JavaScript untuk menampilkan output ke console.</p>',1,'<h3>Instruksi</h3>\n<p>Buatlah program JavaScript yang menampilkan tiga baris output berikut menggunakan <code>console.log()</code>:</p>\n<ol>\n    <li><code>Halo, Dunia!</code></li>\n    <li><code>Saya belajar JavaScript</code></li>\n    <li><code>Ini program pertamaku</code></li>\n</ol>\n<p><strong>Petunjuk:</strong> Gunakan tiga perintah <code>console.log()</code>, masing-masing untuk satu baris output.</p>','javascript','[{\"input\":\"\",\"expected\":\"Halo, Dunia!\"},{\"input\":\"\",\"expected\":\"Saya belajar JavaScript\"},{\"input\":\"\",\"expected\":\"Ini program pertamaku\"}]','// Tulis program JavaScript Anda di sini\n// Tampilkan tiga baris output menggunakan console.log()\n\n// Baris 1: \"Halo, Dunia!\"\n\n// Baris 2: \"Saya belajar JavaScript\"\n\n// Baris 3: \"Ini program pertamaku\"\n','','',0,'training','',1774971660,1774971660),(3,2,'­ƒÆ╗ Latihan 1: Hello World JavaScript','<p>Latihan pertama: tulis program JavaScript untuk menampilkan output ke console.</p>',1,'<h3>Instruksi</h3>\n<p>Buatlah program JavaScript yang menampilkan tiga baris output berikut menggunakan <code>console.log()</code>:</p>\n<ol>\n    <li><code>Halo, Dunia!</code></li>\n    <li><code>Saya belajar JavaScript</code></li>\n    <li><code>Ini program pertamaku</code></li>\n</ol>\n<p><strong>Petunjuk:</strong> Gunakan tiga perintah <code>console.log()</code>, masing-masing untuk satu baris output.</p>','javascript','[{\"input\":\"\",\"expected\":\"Halo, Dunia!\"},{\"input\":\"\",\"expected\":\"Saya belajar JavaScript\"},{\"input\":\"\",\"expected\":\"Ini program pertamaku\"}]','// Tulis program JavaScript Anda di sini\n// Tampilkan tiga baris output menggunakan console.log()\n\n// Baris 1: \"Halo, Dunia!\"\n\n// Baris 2: \"Saya belajar JavaScript\"\n\n// Baris 3: \"Ini program pertamaku\"\n','','',0,'training','',1774971911,1774971911),(4,2,'­ƒÆ╗ Latihan 2: Eksplorasi Variabel dan Tipe Data','<p>Latihan membuat dan menampilkan berbagai variabel dengan tipe data berbeda.</p>',1,'<h3>Instruksi</h3>\n<p>Lengkapi kode berikut untuk:</p>\n<ol>\n    <li>Buat variabel <code>nama</code> (String) berisi nama Anda</li>\n    <li>Buat variabel <code>usia</code> (Number) berisi usia Anda</li>\n    <li>Buat variabel <code>lulus</code> (Boolean) bernilai <code>true</code></li>\n    <li>Buat array <code>mataPelajaran</code> berisi 3 nama mata pelajaran</li>\n    <li>Tampilkan semua variabel dengan <code>console.log()</code></li>\n</ol>\n<p>Output harus memiliki format: <code>Nama: [nama]</code>, <code>Usia: [usia]</code>, <code>Lulus: true</code>, <code>Mapel: [mapel1],[mapel2],[mapel3]</code></p>','javascript','[{\"input\":\"\",\"expected\":\"Nama: Ahmad\"},{\"input\":\"\",\"expected\":\"Usia: 17\"},{\"input\":\"\",\"expected\":\"Lulus: true\"}]','// Latihan: Variabel dan Tipe Data\n// Instruksi: Lengkapi kode di bawah ini\n\n// 1. Buat variabel nama (String)\nlet nama = \"Ahmad\";\n\n// 2. Buat variabel usia (Number)\nlet usia = 17;\n\n// 3. Buat variabel lulus (Boolean)\nlet lulus = true;\n\n// 4. Buat array mataPelajaran dengan 3 elemen\nlet mataPelajaran = [\"Matematika\", \"Bahasa Indonesia\", \"JavaScript\"];\n\n// 5. Tampilkan dengan console.log()\nconsole.log(\"Nama: \" + nama);\nconsole.log(\"Usia: \" + usia);\nconsole.log(\"Lulus: \" + lulus);\nconsole.log(\"Mapel: \" + mataPelajaran.join(\",\"));\n','','',0,'training','',1774971911,1774971911),(5,2,'­ƒÄ» Ujian 3: Kalkulator Sederhana (Mode Ujian)','<p><strong>Mode Ujian</strong>: Kerjakan tanpa bantuan. Gunakan operator JavaScript untuk membuat kalkulator.</p>',1,'<h3>Instruksi</h3>\n<p>Buatlah fungsi <code>kalkulator(a, operator, b)</code> yang menerima dua angka dan satu operator (\"+\", \"-\", \"*\", \"/\"), lalu mengembalikan hasil operasinya.</p>\n<p><strong>Contoh:</strong></p>\n<ul>\n    <li><code>kalkulator(10, \"+\", 5)</code> ÔåÆ <code>15</code></li>\n    <li><code>kalkulator(10, \"-\", 3)</code> ÔåÆ <code>7</code></li>\n    <li><code>kalkulator(4, \"*\", 5)</code> ÔåÆ <code>20</code></li>\n    <li><code>kalkulator(10, \"/\", 2)</code> ÔåÆ <code>5</code></li>\n</ul>','javascript','[{\"input\":\"10, \\\"+\\\", 5\",\"expected\":\"15\"},{\"input\":\"10, \\\"-\\\", 3\",\"expected\":\"7\"},{\"input\":\"4, \\\"*\\\", 5\",\"expected\":\"20\"},{\"input\":\"10, \\\"/\\\", 2\",\"expected\":\"5\"}]','// Mode Ujian: Kerjakan secara mandiri!\n// Buat fungsi kalkulator\n\nfunction kalkulator(a, operator, b) {\n    // Tulis kode Anda di sini\n    \n}\n\n// Test\nconsole.log(kalkulator(10, \"+\", 5));  // 15\nconsole.log(kalkulator(10, \"-\", 3));  // 7\nconsole.log(kalkulator(4, \"*\", 5));   // 20\nconsole.log(kalkulator(10, \"/\", 2));  // 5\n','','',0,'exam','',1774971911,1774971911),(6,2,'­ƒÆ╗ Latihan 4: Cek Nilai Siswa (Mode Latihan)','<p>Latihan menggunakan if-else untuk membuat program penilai nilai siswa.</p>',1,'<h3>Instruksi</h3>\n<p>Buatlah fungsi <code>cekNilai(nilai)</code> yang menerima angka nilai (0-100) dan mengembalikan keterangan predikat:</p>\n<ul>\n    <li>90-100 ÔåÆ <code>\"A - Sangat Baik\"</code></li>\n    <li>80-89 ÔåÆ <code>\"B - Baik\"</code></li>\n    <li>70-79 ÔåÆ <code>\"C - Cukup\"</code></li>\n    <li>60-69 ÔåÆ <code>\"D - Kurang\"</code></li>\n    <li>0-59 ÔåÆ <code>\"E - Tidak Lulus\"</code></li>\n</ul>','javascript','[{\"input\":\"95\",\"expected\":\"A - Sangat Baik\"},{\"input\":\"82\",\"expected\":\"B - Baik\"},{\"input\":\"75\",\"expected\":\"C - Cukup\"},{\"input\":\"65\",\"expected\":\"D - Kurang\"},{\"input\":\"45\",\"expected\":\"E - Tidak Lulus\"}]','// Latihan: Cek Nilai Siswa\n// Buatlah fungsi cekNilai dengan if-else\n\nfunction cekNilai(nilai) {\n    // Tulis kode Anda di sini menggunakan if-else if-else\n    \n}\n\n// Test\nconsole.log(cekNilai(95));  // \"A - Sangat Baik\"\nconsole.log(cekNilai(82));  // \"B - Baik\"\nconsole.log(cekNilai(75));  // \"C - Cukup\"\nconsole.log(cekNilai(65));  // \"D - Kurang\"\nconsole.log(cekNilai(45));  // \"E - Tidak Lulus\"\n','','',0,'training','',1774971912,1774971912),(7,2,'­ƒÄ» Ujian 5: FizzBuzz Challenge (Mode Ujian)','<p><strong>Mode Ujian</strong>: Kerjakan mandiri. Tantangan klasik menggunakan loop dan kondisi.</p>',1,'<h3>Instruksi: FizzBuzz</h3>\n<p>Buatlah fungsi <code>fizzBuzz(n)</code> yang mengembalikan array dari 1 sampai n dengan aturan:</p>\n<ul>\n    <li>Kelipatan <strong>3</strong>: ganti dengan <code>\"Fizz\"</code></li>\n    <li>Kelipatan <strong>5</strong>: ganti dengan <code>\"Buzz\"</code></li>\n    <li>Kelipatan <strong>3 dan 5</strong>: ganti dengan <code>\"FizzBuzz\"</code></li>\n    <li>Angka lain: tetap angka (bukan string)</li>\n</ul>\n<p><strong>Contoh:</strong> <code>fizzBuzz(15)</code> ÔåÆ <code>[1,2,\"Fizz\",4,\"Buzz\",\"Fizz\",7,8,\"Fizz\",\"Buzz\",11,\"Fizz\",13,14,\"FizzBuzz\"]</code></p>','javascript','[{\"input\":\"15\",\"expected\":\"[1,2,\\\"Fizz\\\",4,\\\"Buzz\\\",\\\"Fizz\\\",7,8,\\\"Fizz\\\",\\\"Buzz\\\",11,\\\"Fizz\\\",13,14,\\\"FizzBuzz\\\"]\"},{\"input\":\"5\",\"expected\":\"[1,2,\\\"Fizz\\\",4,\\\"Buzz\\\"]\"}]','// Mode Ujian: FizzBuzz Challenge\n// Buatlah fungsi fizzBuzz(n)\n\nfunction fizzBuzz(n) {\n    // Tulis kode Anda di sini\n    // Petunjuk: gunakan for loop dan operator modulo (%)\n    \n}\n\n// Test\nconsole.log(JSON.stringify(fizzBuzz(15)));\nconsole.log(JSON.stringify(fizzBuzz(5)));\n','','',0,'exam','',1774971912,1774971912),(8,2,'­ƒÆ╗ Latihan 6: Fungsi Perhitungan (Mode Latihan)','<p>Latihan membuat berbagai fungsi matematika menggunakan function declaration dan arrow function.</p>',1,'<h3>Instruksi</h3>\n<p>Buatlah fungsi-fungsi berikut:</p>\n<ol>\n    <li><code>luasLingkaran(r)</code>: mengembalikan luas lingkaran dengan radius r (gunakan <code>Math.PI</code>), dibulatkan 2 desimal</li>\n    <li><code>faktorial(n)</code>: mengembalikan faktorial dari n (n! = n ├ù (n-1) ├ù ... ├ù 1, 0! = 1)</li>\n    <li><code>pangkat(base, exp)</code>: mengembalikan base pangkat exp tanpa menggunakan operator **</li>\n</ol>','javascript','[{\"input\":\"5\",\"expected\":\"78.54\"},{\"input\":\"5\",\"expected\":\"120\"},{\"input\":\"2, 10\",\"expected\":\"1024\"}]','// Latihan: Fungsi Perhitungan\n\n// 1. Fungsi luas lingkaran\n// Rumus: ¤Ç ├ù r┬▓\nfunction luasLingkaran(r) {\n    // Tulis kode di sini\n    \n}\n\n// 2. Fungsi faktorial (rekursif atau iteratif)\nfunction faktorial(n) {\n    // Tulis kode di sini\n    \n}\n\n// 3. Fungsi pangkat (gunakan loop, bukan **)\nfunction pangkat(base, exp) {\n    // Tulis kode di sini\n    \n}\n\n// Test\nconsole.log(luasLingkaran(5));   // 78.54\nconsole.log(faktorial(5));       // 120\nconsole.log(pangkat(2, 10));     // 1024\n','','',0,'training','',1774971912,1774971912),(9,2,'­ƒÆ╗ Latihan 7: Manipulasi DOM (Mode Latihan)','<p>Latihan memanipulasi elemen HTML menggunakan JavaScript dan DOM API.</p>',1,'<h3>Instruksi</h3>\n<p>Gunakan JavaScript untuk memanipulasi halaman:</p>\n<ol>\n    <li>Ubah teks elemen <code>#judul</code> menjadi <code>\"JavaScript DOM!\"</code></li>\n    <li>Ubah warna background <code>#kotak</code> menjadi <code>\"steelblue\"</code></li>\n    <li>Tambahkan class <code>\"aktif\"</code> ke elemen <code>#paragraf</code></li>\n    <li>Tambahkan item baru <code>\"Item 3\"</code> ke <code>#daftar</code></li>\n</ol>\n<p>Gunakan <code>console.log()</code> untuk konfirmasi setiap langkah.</p>','javascript','[{\"input\":\"\",\"expected\":\"JavaScript DOM!\"},{\"input\":\"\",\"expected\":\"steelblue\"},{\"input\":\"\",\"expected\":\"true\"},{\"input\":\"\",\"expected\":\"3\"}]','// Latihan: Manipulasi DOM\n// Gunakan getElementById, querySelector, classList, dll.\n\n// 1. Ubah judul\nlet judul = document.getElementById(\"judul\");\n// ubah textContent judul di sini\n\n// 2. Ubah warna background kotak\nlet kotak = document.getElementById(\"kotak\");\n// ubah style backgroundColor di sini\n\n// 3. Tambah class \"aktif\" ke paragraf\nlet paragraf = document.getElementById(\"paragraf\");\n// tambah class di sini\n\n// 4. Tambah item baru ke daftar\nlet daftar = document.getElementById(\"daftar\");\n// buat li baru dan append di sini\n\nconsole.log(\"Judul:\", judul.textContent);\nconsole.log(\"Kotak bg:\", kotak.style.backgroundColor);\nconsole.log(\"Paragraf aktif:\", paragraf.classList.contains(\"aktif\"));\nconsole.log(\"Jumlah item:\", daftar.children.length);\n','<div id=\"kontainer\">\n  <h2 id=\"judul\">Teks Asli</h2>\n  <p id=\"paragraf\">Ini adalah paragraf.</p>\n  <div id=\"kotak\" style=\"width:100px;height:100px;background:gray;margin:10px 0;\"></div>\n  <ul id=\"daftar\">\n    <li>Item 1</li>\n    <li>Item 2</li>\n  </ul>\n</div>','.aktif { background-color: green !important; color: white; padding: 5px; }\n#kontainer { font-family: Arial, sans-serif; padding: 10px; }',0,'training','',1774971912,1774971912),(10,2,'­ƒÆ╗ Latihan 1: Hello World JavaScript','<p>Latihan pertama: tulis program JavaScript untuk menampilkan output ke console.</p>',1,'<h3>Instruksi</h3>\n<p>Buatlah program JavaScript yang menampilkan tiga baris output berikut menggunakan <code>console.log()</code>:</p>\n<ol>\n    <li><code>Halo, Dunia!</code></li>\n    <li><code>Saya belajar JavaScript</code></li>\n    <li><code>Ini program pertamaku</code></li>\n</ol>\n<p><strong>Petunjuk:</strong> Gunakan tiga perintah <code>console.log()</code>, masing-masing untuk satu baris output.</p>','javascript','[{\"input\":\"\",\"expected\":\"Halo, Dunia!\"},{\"input\":\"\",\"expected\":\"Saya belajar JavaScript\"},{\"input\":\"\",\"expected\":\"Ini program pertamaku\"}]','// Tulis program JavaScript Anda di sini\n// Tampilkan tiga baris output menggunakan console.log()\n\n// Baris 1: \"Halo, Dunia!\"\n\n// Baris 2: \"Saya belajar JavaScript\"\n\n// Baris 3: \"Ini program pertamaku\"\n','','',0,'training','',1774971974,1774971974),(11,2,'­ƒÆ╗ Latihan 1: Hello World JavaScript','<p>Latihan pertama: tulis program JavaScript untuk menampilkan output ke console.</p>',1,'Instruksi\r\nBuatlah program JavaScript yang menampilkan tiga baris output berikut menggunakan console.log():\r\n\r\n    Halo, Dunia!\r\n    Saya belajar JavaScript\r\n    Ini program pertamaku\r\n\r\nPetunjuk: Gunakan tiga perintah console.log(), masing-masing untuk satu baris output.','javascript','[{\"input\":\"\",\"expected\":\"Halo, Dunia!\"},{\"input\":\"\",\"expected\":\"Saya belajar JavaScript\"},{\"input\":\"\",\"expected\":\"Ini program pertamaku\"}]','// Tulis program JavaScript Anda di sini\r\n// Tampilkan tiga baris output menggunakan console.log()\r\n\r\n// Baris 1: \"Halo, Dunia!\"\r\n\r\n// Baris 2: \"Saya belajar JavaScript\"\r\n\r\n// Baris 3: \"Ini program pertamaku\"\r\n','','',0,'training','',1774972096,1775235709),(12,2,'­ƒÆ╗ Latihan 2: Eksplorasi Variabel dan Tipe Data','<p>Latihan membuat dan menampilkan berbagai variabel dengan tipe data berbeda.</p>',1,'Instruksi\r\nLengkapi kode berikut untuk:\r\n\r\n    Buat variabel nama (String) berisi nama Anda\r\n    Buat variabel usia (Number) berisi usia Anda\r\n    Buat variabel lulus (Boolean) bernilai true\r\n    Buat array mataPelajaran berisi 3 nama mata pelajaran\r\n    Tampilkan semua variabel dengan console.log()\r\n\r\nOutput harus memiliki format: Nama: [nama], Usia: [usia], Lulus: true, Mapel: [mapel1],[mapel2],[mapel3]','javascript','[{\"input\":\"\",\"expected\":\"Nama: Ahmad\"},{\"input\":\"\",\"expected\":\"Usia: 17\"},{\"input\":\"\",\"expected\":\"Lulus: true\"}]','// Latihan: Variabel dan Tipe Data\r\n// Instruksi: Lengkapi kode di bawah ini\r\n\r\n// 1. Buat variabel nama (String)\r\nlet nama = \"Ahmad\";\r\n\r\n// 2. Buat variabel usia (Number)\r\nlet usia = 17;\r\n\r\n// 3. Buat variabel lulus (Boolean)\r\nlet lulus = true;\r\n\r\n// 4. Buat array mataPelajaran dengan 3 elemen\r\nlet mataPelajaran = [\"Matematika\", \"Bahasa Indonesia\", \"JavaScript\"];\r\n\r\n// 5. Tampilkan dengan console.log()\r\nconsole.log(\"Nama: \" + nama);\r\nconsole.log(\"Usia: \" + usia);\r\nconsole.log(\"Lulus: \" + lulus);\r\nconsole.log(\"Mapel: \" + mataPelajaran.join(\",\"));\r\n','','',0,'training','',1774972096,1775489281),(13,2,'­ƒÄ» Ujian 3: Kalkulator Sederhana (Mode Ujian)','<p><strong>Mode Ujian</strong>: Kerjakan tanpa bantuan. Gunakan operator JavaScript untuk membuat kalkulator.</p>',1,'<h3>Instruksi</h3>\n<p>Buatlah fungsi <code>kalkulator(a, operator, b)</code> yang menerima dua angka dan satu operator (\"+\", \"-\", \"*\", \"/\"), lalu mengembalikan hasil operasinya.</p>\n<p><strong>Contoh:</strong></p>\n<ul>\n    <li><code>kalkulator(10, \"+\", 5)</code> ÔåÆ <code>15</code></li>\n    <li><code>kalkulator(10, \"-\", 3)</code> ÔåÆ <code>7</code></li>\n    <li><code>kalkulator(4, \"*\", 5)</code> ÔåÆ <code>20</code></li>\n    <li><code>kalkulator(10, \"/\", 2)</code> ÔåÆ <code>5</code></li>\n</ul>','javascript','[{\"input\":\"10, \\\"+\\\", 5\",\"expected\":\"15\"},{\"input\":\"10, \\\"-\\\", 3\",\"expected\":\"7\"},{\"input\":\"4, \\\"*\\\", 5\",\"expected\":\"20\"},{\"input\":\"10, \\\"/\\\", 2\",\"expected\":\"5\"}]','// Mode Ujian: Kerjakan secara mandiri!\n// Buat fungsi kalkulator\n\nfunction kalkulator(a, operator, b) {\n    // Tulis kode Anda di sini\n    \n}\n\n// Test\nconsole.log(kalkulator(10, \"+\", 5));  // 15\nconsole.log(kalkulator(10, \"-\", 3));  // 7\nconsole.log(kalkulator(4, \"*\", 5));   // 20\nconsole.log(kalkulator(10, \"/\", 2));  // 5\n','','',0,'exam','',1774972096,1774972096),(14,2,'­ƒÆ╗ Latihan 4: Cek Nilai Siswa (Mode Latihan)','<p>Latihan menggunakan if-else untuk membuat program penilai nilai siswa.</p>',1,'<h3>Instruksi</h3>\n<p>Buatlah fungsi <code>cekNilai(nilai)</code> yang menerima angka nilai (0-100) dan mengembalikan keterangan predikat:</p>\n<ul>\n    <li>90-100 ÔåÆ <code>\"A - Sangat Baik\"</code></li>\n    <li>80-89 ÔåÆ <code>\"B - Baik\"</code></li>\n    <li>70-79 ÔåÆ <code>\"C - Cukup\"</code></li>\n    <li>60-69 ÔåÆ <code>\"D - Kurang\"</code></li>\n    <li>0-59 ÔåÆ <code>\"E - Tidak Lulus\"</code></li>\n</ul>','javascript','[{\"input\":\"95\",\"expected\":\"A - Sangat Baik\"},{\"input\":\"82\",\"expected\":\"B - Baik\"},{\"input\":\"75\",\"expected\":\"C - Cukup\"},{\"input\":\"65\",\"expected\":\"D - Kurang\"},{\"input\":\"45\",\"expected\":\"E - Tidak Lulus\"}]','// Latihan: Cek Nilai Siswa\n// Buatlah fungsi cekNilai dengan if-else\n\nfunction cekNilai(nilai) {\n    // Tulis kode Anda di sini menggunakan if-else if-else\n    \n}\n\n// Test\nconsole.log(cekNilai(95));  // \"A - Sangat Baik\"\nconsole.log(cekNilai(82));  // \"B - Baik\"\nconsole.log(cekNilai(75));  // \"C - Cukup\"\nconsole.log(cekNilai(65));  // \"D - Kurang\"\nconsole.log(cekNilai(45));  // \"E - Tidak Lulus\"\n','','',0,'training','',1774972097,1774972097),(15,2,'­ƒÄ» Ujian 5: FizzBuzz Challenge (Mode Ujian)','<p><strong>Mode Ujian</strong>: Kerjakan mandiri. Tantangan klasik menggunakan loop dan kondisi.</p>',1,'<h3>Instruksi: FizzBuzz</h3>\n<p>Buatlah fungsi <code>fizzBuzz(n)</code> yang mengembalikan array dari 1 sampai n dengan aturan:</p>\n<ul>\n    <li>Kelipatan <strong>3</strong>: ganti dengan <code>\"Fizz\"</code></li>\n    <li>Kelipatan <strong>5</strong>: ganti dengan <code>\"Buzz\"</code></li>\n    <li>Kelipatan <strong>3 dan 5</strong>: ganti dengan <code>\"FizzBuzz\"</code></li>\n    <li>Angka lain: tetap angka (bukan string)</li>\n</ul>\n<p><strong>Contoh:</strong> <code>fizzBuzz(15)</code> ÔåÆ <code>[1,2,\"Fizz\",4,\"Buzz\",\"Fizz\",7,8,\"Fizz\",\"Buzz\",11,\"Fizz\",13,14,\"FizzBuzz\"]</code></p>','javascript','[{\"input\":\"15\",\"expected\":\"[1,2,\\\"Fizz\\\",4,\\\"Buzz\\\",\\\"Fizz\\\",7,8,\\\"Fizz\\\",\\\"Buzz\\\",11,\\\"Fizz\\\",13,14,\\\"FizzBuzz\\\"]\"},{\"input\":\"5\",\"expected\":\"[1,2,\\\"Fizz\\\",4,\\\"Buzz\\\"]\"}]','// Mode Ujian: FizzBuzz Challenge\n// Buatlah fungsi fizzBuzz(n)\n\nfunction fizzBuzz(n) {\n    // Tulis kode Anda di sini\n    // Petunjuk: gunakan for loop dan operator modulo (%)\n    \n}\n\n// Test\nconsole.log(JSON.stringify(fizzBuzz(15)));\nconsole.log(JSON.stringify(fizzBuzz(5)));\n','','',0,'exam','',1774972097,1774972097),(16,2,'­ƒÆ╗ Latihan 6: Fungsi Perhitungan (Mode Latihan)','<p>Latihan membuat berbagai fungsi matematika menggunakan function declaration dan arrow function.</p>',1,'<h3>Instruksi</h3>\n<p>Buatlah fungsi-fungsi berikut:</p>\n<ol>\n    <li><code>luasLingkaran(r)</code>: mengembalikan luas lingkaran dengan radius r (gunakan <code>Math.PI</code>), dibulatkan 2 desimal</li>\n    <li><code>faktorial(n)</code>: mengembalikan faktorial dari n (n! = n ├ù (n-1) ├ù ... ├ù 1, 0! = 1)</li>\n    <li><code>pangkat(base, exp)</code>: mengembalikan base pangkat exp tanpa menggunakan operator **</li>\n</ol>','javascript','[{\"input\":\"5\",\"expected\":\"78.54\"},{\"input\":\"5\",\"expected\":\"120\"},{\"input\":\"2, 10\",\"expected\":\"1024\"}]','// Latihan: Fungsi Perhitungan\n\n// 1. Fungsi luas lingkaran\n// Rumus: ¤Ç ├ù r┬▓\nfunction luasLingkaran(r) {\n    // Tulis kode di sini\n    \n}\n\n// 2. Fungsi faktorial (rekursif atau iteratif)\nfunction faktorial(n) {\n    // Tulis kode di sini\n    \n}\n\n// 3. Fungsi pangkat (gunakan loop, bukan **)\nfunction pangkat(base, exp) {\n    // Tulis kode di sini\n    \n}\n\n// Test\nconsole.log(luasLingkaran(5));   // 78.54\nconsole.log(faktorial(5));       // 120\nconsole.log(pangkat(2, 10));     // 1024\n','','',0,'training','',1774972097,1774972097),(17,2,'­ƒÆ╗ Latihan 7: Manipulasi DOM (Mode Latihan)','<p>Latihan memanipulasi elemen HTML menggunakan JavaScript dan DOM API.</p>',1,'<h3>Instruksi</h3>\n<p>Gunakan JavaScript untuk memanipulasi halaman:</p>\n<ol>\n    <li>Ubah teks elemen <code>#judul</code> menjadi <code>\"JavaScript DOM!\"</code></li>\n    <li>Ubah warna background <code>#kotak</code> menjadi <code>\"steelblue\"</code></li>\n    <li>Tambahkan class <code>\"aktif\"</code> ke elemen <code>#paragraf</code></li>\n    <li>Tambahkan item baru <code>\"Item 3\"</code> ke <code>#daftar</code></li>\n</ol>\n<p>Gunakan <code>console.log()</code> untuk konfirmasi setiap langkah.</p>','javascript','[{\"input\":\"\",\"expected\":\"JavaScript DOM!\"},{\"input\":\"\",\"expected\":\"steelblue\"},{\"input\":\"\",\"expected\":\"true\"},{\"input\":\"\",\"expected\":\"3\"}]','// Latihan: Manipulasi DOM\n// Gunakan getElementById, querySelector, classList, dll.\n\n// 1. Ubah judul\nlet judul = document.getElementById(\"judul\");\n// ubah textContent judul di sini\n\n// 2. Ubah warna background kotak\nlet kotak = document.getElementById(\"kotak\");\n// ubah style backgroundColor di sini\n\n// 3. Tambah class \"aktif\" ke paragraf\nlet paragraf = document.getElementById(\"paragraf\");\n// tambah class di sini\n\n// 4. Tambah item baru ke daftar\nlet daftar = document.getElementById(\"daftar\");\n// buat li baru dan append di sini\n\nconsole.log(\"Judul:\", judul.textContent);\nconsole.log(\"Kotak bg:\", kotak.style.backgroundColor);\nconsole.log(\"Paragraf aktif:\", paragraf.classList.contains(\"aktif\"));\nconsole.log(\"Jumlah item:\", daftar.children.length);\n','<div id=\"kontainer\">\n  <h2 id=\"judul\">Teks Asli</h2>\n  <p id=\"paragraf\">Ini adalah paragraf.</p>\n  <div id=\"kotak\" style=\"width:100px;height:100px;background:gray;margin:10px 0;\"></div>\n  <ul id=\"daftar\">\n    <li>Item 1</li>\n    <li>Item 2</li>\n  </ul>\n</div>','.aktif { background-color: green !important; color: white; padding: 5px; }\n#kontainer { font-family: Arial, sans-serif; padding: 10px; }',0,'training','',1774972098,1774972098),(18,2,'­ƒÄ» Ujian 8: Aplikasi Counter (Mode Ujian)','<p><strong>Mode Ujian</strong>: Buat aplikasi counter menggunakan event handling JavaScript.</p>',1,'<h3>Instruksi: Aplikasi Counter</h3>\n<p>Buat aplikasi penghitung (counter) yang:</p>\n<ol>\n    <li>Tombol <strong>\"+ Tambah\"</strong>: tambah hitungan sebesar 1, update teks <code>#counter-display</code></li>\n    <li>Tombol <strong>\"- Kurang\"</strong>: kurangi hitungan sebesar 1 (minimal 0), update teks</li>\n    <li>Tombol <strong>\"Reset\"</strong>: kembalikan hitungan ke 0, update teks</li>\n    <li>Saat hitungan berubah, tampilkan status di <code>#status</code>: \"Lebih dari 5!\" jika > 5, \"Normal\" jika <= 5</li>\n</ol>','javascript','[{\"input\":\"click tambah\",\"expected\":\"Hitungan: 1\"},{\"input\":\"click reset\",\"expected\":\"Hitungan: 0\"}]','// Mode Ujian: Aplikasi Counter\n// Buat event handler untuk ketiga tombol\n\nlet hitungan = 0;\n\nfunction updateDisplay() {\n    document.getElementById(\"counter-display\").textContent = \"Hitungan: \" + hitungan;\n    // Tulis kode untuk update #status di sini\n    \n}\n\n// Event listener untuk tombol Tambah\ndocument.getElementById(\"btn-tambah\").addEventListener(\"click\", function() {\n    // Tulis kode di sini\n    \n});\n\n// Event listener untuk tombol Kurang\ndocument.getElementById(\"btn-kurang\").addEventListener(\"click\", function() {\n    // Tulis kode di sini (hitungan minimal 0)\n    \n});\n\n// Event listener untuk tombol Reset\ndocument.getElementById(\"btn-reset\").addEventListener(\"click\", function() {\n    // Tulis kode di sini\n    \n});\n\n// Inisialisasi\nupdateDisplay();\n','<div id=\"app\">\n  <h2 id=\"counter-display\">Hitungan: 0</h2>\n  <button id=\"btn-tambah\">+ Tambah</button>\n  <button id=\"btn-kurang\">- Kurang</button>\n  <button id=\"btn-reset\">Reset</button>\n  <p id=\"status\"></p>\n</div>','#app { font-family: Arial; text-align: center; padding: 20px; }\nbutton { padding: 8px 16px; margin: 5px; font-size: 16px; cursor: pointer; }\n#btn-tambah { background: #4CAF50; color: white; border: none; border-radius: 4px; }\n#btn-kurang { background: #f44336; color: white; border: none; border-radius: 4px; }\n#btn-reset { background: #2196F3; color: white; border: none; border-radius: 4px; }',0,'exam','',1774972098,1774972098),(19,2,'­ƒÆ╗ Proyek Akhir: Kalkulator Lengkap (Mode Latihan)','<p>Proyek akhir: buat aplikasi kalkulator yang mengintegrasikan DOM, events, fungsi, dan kondisi.</p>',1,'<h3>Instruksi: Proyek Kalkulator</h3>\n<p>Buat kalkulator yang:</p>\n<ol>\n    <li>Ambil nilai dari input <code>#angka1</code> dan <code>#angka2</code></li>\n    <li>Ambil operator dari <code>#operator</code></li>\n    <li>Saat tombol <code>#hitung</code> diklik, hitung dan tampilkan hasil di <code>#hasil</code></li>\n    <li>Tangani pembagian dengan 0 (tampilkan pesan error)</li>\n    <li>Tampilkan riwayat perhitungan di <code>#daftar-riwayat</code></li>\n</ol>\n<p><strong>Gabungkan:</strong> functions, DOM manipulation, event handling, if-else, dan error handling!</p>','javascript','[{\"input\":\"\",\"expected\":\"Kalkulator siap digunakan!\"}]','// Proyek Akhir: Kalkulator Sederhana\n// Gabungkan semua yang telah dipelajari!\n\nlet riwayat = [];\n\n// Fungsi perhitungan\nfunction hitung(a, op, b) {\n    // Tulis fungsi kalkulator di sini\n    // Tangani pembagian dengan nol!\n    \n}\n\n// Fungsi update tampilan riwayat\nfunction updateRiwayat() {\n    let daftar = document.getElementById(\"daftar-riwayat\");\n    daftar.innerHTML = \"\";\n    // Tampilkan riwayat terakhir (maks 5)\n    \n}\n\n// Event listener untuk tombol hitung\ndocument.getElementById(\"hitung\").addEventListener(\"click\", function() {\n    let a = parseFloat(document.getElementById(\"angka1\").value);\n    let b = parseFloat(document.getElementById(\"angka2\").value);\n    let op = document.getElementById(\"operator\").value;\n    let hasilEl = document.getElementById(\"hasil\");\n    \n    // Validasi input\n    if (isNaN(a) || isNaN(b)) {\n        hasilEl.textContent = \"Masukkan angka yang valid!\";\n        hasilEl.style.color = \"red\";\n        return;\n    }\n    \n    // Hitung dan tampilkan\n    // Tulis kode di sini\n    \n});\n\nconsole.log(\"Kalkulator siap digunakan!\");\n','<div id=\"kalkulator\" style=\"max-width:300px;margin:0 auto;\">\n  <h3>Kalkulator Sederhana</h3>\n  <input type=\"number\" id=\"angka1\" placeholder=\"Angka 1\" style=\"width:100%;padding:8px;margin:4px 0;\">\n  <input type=\"number\" id=\"angka2\" placeholder=\"Angka 2\" style=\"width:100%;padding:8px;margin:4px 0;\">\n  <select id=\"operator\" style=\"width:100%;padding:8px;margin:4px 0;\">\n    <option value=\"+\">Tambah (+)</option>\n    <option value=\"-\">Kurang (-)</option>\n    <option value=\"*\">Kali (*)</option>\n    <option value=\"/\">Bagi (/)</option>\n  </select>\n  <button id=\"hitung\" style=\"width:100%;padding:10px;background:#4CAF50;color:white;border:none;border-radius:4px;font-size:16px;cursor:pointer;\">Hitung</button>\n  <div id=\"hasil\" style=\"margin-top:10px;padding:10px;background:#f0f0f0;border-radius:4px;font-size:18px;min-height:40px;\"></div>\n  <div id=\"riwayat\" style=\"margin-top:10px;\">\n    <h4>Riwayat:</h4>\n    <ul id=\"daftar-riwayat\" style=\"list-style:none;padding:0;\"></ul>\n  </div>\n</div>','body { font-family: Arial, sans-serif; padding: 20px; }\ninput:focus, select:focus { outline: 2px solid #4CAF50; }',0,'training','',1774972098,1774972098),(20,2,'­ƒÆ╗ Latihan 1.1 ÔÇö Profil Siswa','<p>Buat variabel untuk menyimpan data profil siswa dan tampilkan ke console. <strong>Mode: Latihan</strong> ÔÇö AI akan membantu jika Anda kesulitan.</p>',1,'<h3>­ƒôï Tugas</h3>\n<p>Buatlah variabel-variabel berikut dan tampilkan dengan <code>console.log()</code>:</p>\n<ol>\n  <li>Variabel <code>const</code> bernama <code>namaSiswa</code> berisi <code>\"Budi Santoso\"</code></li>\n  <li>Variabel <code>let</code> bernama <code>umur</code> berisi angka <code>17</code></li>\n  <li>Variabel <code>let</code> bernama <code>isStudent</code> bernilai <code>true</code></li>\n  <li>Panggil <code>console.log()</code> untuk masing-masing variabel</li>\n</ol>','javascript','[{\"input\":\"\",\"expected\":\"Budi Santoso\"},{\"input\":\"\",\"expected\":\"17\"},{\"input\":\"\",\"expected\":\"true\"}]','// ­ƒÄ» Latihan 1.1: Profil Siswa\n// Lengkapi kode di bawah ini!\n\n// 1. Deklarasikan namaSiswa menggunakan const\nconst namaSiswa = \"Budi Santoso\";\n\n// 2. Deklarasikan umur menggunakan let\nlet umur = 17;\n\n// 3. Deklarasikan isStudent menggunakan let\nlet isStudent = true;\n\n// 4. Tampilkan ketiga variabel\nconsole.log(namaSiswa);\nconsole.log(umur);\nconsole.log(isStudent);\n','','',0,'training','',1775624081,1775624081),(21,2,'­ƒÆ╗ Latihan 1.2 ÔÇö Hitung Total Belanja','<p>Implementasikan operator aritmatika untuk menghitung total belanja. <strong>Mode: Latihan</strong>.</p>',1,'<h3>­ƒôï Tugas</h3>\n<p>Buatlah fungsi <code>totalBelanja(harga, jumlah)</code> yang:</p>\n<ul>\n  <li>Menerima dua parameter: <code>harga</code> (harga satuan) dan <code>jumlah</code> (banyak barang)</li>\n  <li>Mengembalikan hasil perkalian <code>harga ├ù jumlah</code></li>\n</ul>\n<p>Contoh: <code>totalBelanja(5000, 3)</code> ÔåÆ <code>15000</code></p>','javascript','[{\"input\":\"5000, 3\",\"expected\":\"15000\"},{\"input\":\"12000, 4\",\"expected\":\"48000\"},{\"input\":\"2500, 10\",\"expected\":\"25000\"}]','// ­ƒÄ» Latihan 1.2: Hitung Total Belanja\n\nfunction totalBelanja(harga, jumlah) {\n    // Tulis kode Anda di sini\n    \n}\n\n// Test ÔÇö jangan hapus!\nconsole.log(totalBelanja(5000, 3));    // 15000\nconsole.log(totalBelanja(12000, 4));   // 48000\nconsole.log(totalBelanja(2500, 10));   // 25000\n','','',0,'training','',1775624082,1775624082),(22,2,'­ƒÄ» Ujian 1.3 ÔÇö Kartu Identitas Digital (Mode Ujian)','<p><strong>Mode: Ujian Mandiri</strong> ÔÇö Kerjakan tanpa bantuan AI. Gunakan template literal untuk membuat output profesional.</p>',1,'<h3>­ƒôï Tugas Ujian</h3>\n<p>Buatlah fungsi <code>kartuIdentitas(nama, usia, kelas)</code> yang menggunakan <strong>template literal</strong> dan mengembalikan string dengan format persis:</p>\n<pre style=\"background:#1e1e2e;color:#cdd6f4;padding:12px;border-radius:6px;\">Nama: Budi Santoso | Usia: 17 | Kelas: 11 PPLG</pre>\n<p>Perhatikan: pisah dengan <code>\" | \"</code> (spasi-pipe-spasi), gunakan template literal.</p>','javascript','[{\"input\":\"Budi Santoso, 17, 11 PPLG\",\"expected\":\"Nama: Budi Santoso | Usia: 17 | Kelas: 11 PPLG\"},{\"input\":\"Siti Rahayu, 16, 11 RPL 2\",\"expected\":\"Nama: Siti Rahayu | Usia: 16 | Kelas: 11 RPL 2\"}]','// ­ƒÄ» Ujian 1.3: Kartu Identitas Digital\n// Mode UJIAN ÔÇö kerjakan mandiri!\n\nfunction kartuIdentitas(nama, usia, kelas) {\n    // Gunakan template literal dengan ${}\n    // Return string: \"Nama: [nama] | Usia: [usia] | Kelas: [kelas]\"\n    \n}\n\n// Test\nconsole.log(kartuIdentitas(\"Budi Santoso\", 17, \"11 PPLG\"));\nconsole.log(kartuIdentitas(\"Siti Rahayu\", 16, \"11 RPL 2\"));\n','','',0,'exam','',1775624082,1775624082),(23,2,'­ƒÆ╗ Latihan 2.1 ÔÇö Cek Kompetensi Siswa','<p>Gunakan if-else untuk membuat sistem cek kompetensi siswa. <strong>Mode: Latihan</strong>.</p>',1,'<h3>­ƒôï Tugas</h3>\n<p>Buatlah fungsi <code>cekKompetensi(nilai)</code> yang:</p>\n<ul>\n  <li>Jika <code>nilai >= 75</code> ÔåÆ kembalikan <code>\"Kompeten\"</code></li>\n  <li>Jika nilai di bawah 75 ÔåÆ kembalikan <code>\"Belum Kompeten\"</code></li>\n</ul>','javascript','[{\"input\":\"80\",\"expected\":\"Kompeten\"},{\"input\":\"75\",\"expected\":\"Kompeten\"},{\"input\":\"70\",\"expected\":\"Belum Kompeten\"},{\"input\":\"50\",\"expected\":\"Belum Kompeten\"}]','// ­ƒÄ» Latihan 2.1: Cek Kompetensi Siswa\n\nfunction cekKompetensi(nilai) {\n    // Gunakan if-else\n    \n}\n\n// Test\nconsole.log(cekKompetensi(80));  // \"Kompeten\"\nconsole.log(cekKompetensi(75));  // \"Kompeten\"\nconsole.log(cekKompetensi(70));  // \"Belum Kompeten\"\nconsole.log(cekKompetensi(50));  // \"Belum Kompeten\"\n','','',0,'training','',1775624082,1775624082),(24,2,'­ƒÆ╗ Latihan 2.2 ÔÇö Sapa Berdasarkan Waktu','<p>Implementasikan else if untuk program greeting berdasarkan jam. <strong>Mode: Latihan</strong>.</p>',1,'<h3>­ƒôï Tugas</h3>\n<p>Buatlah fungsi <code>sapaWaktu(jam)</code> yang mengembalikan sapaan sesuai waktu:</p>\n<ul>\n  <li><code>jam &lt; 12</code> ÔåÆ <code>\"Selamat Pagi\"</code></li>\n  <li><code>jam &lt; 18</code> ÔåÆ <code>\"Selamat Siang\"</code></li>\n  <li>selain itu ÔåÆ <code>\"Selamat Malam\"</code></li>\n</ul>','javascript','[{\"input\":\"7\",\"expected\":\"Selamat Pagi\"},{\"input\":\"14\",\"expected\":\"Selamat Siang\"},{\"input\":\"20\",\"expected\":\"Selamat Malam\"}]','// ­ƒÄ» Latihan 2.2: Sapa Berdasarkan Waktu\n\nfunction sapaWaktu(jam) {\n    // Gunakan if - else if - else\n    \n}\n\n// Test\nconsole.log(sapaWaktu(7));   // \"Selamat Pagi\"\nconsole.log(sapaWaktu(14));  // \"Selamat Siang\"\nconsole.log(sapaWaktu(20));  // \"Selamat Malam\"\n','','',0,'training','',1775624083,1775624083),(25,2,'­ƒÄ» Ujian 2.3 ÔÇö Sistem Tiket Bioskop (Mode Ujian)','<p><strong>Mode: Ujian Mandiri</strong> ÔÇö Gunakan operator logika untuk sistem tiket berdasarkan kategori umur.</p>',1,'<h3>­ƒôï Tugas Ujian</h3>\n<p>Buatlah fungsi <code>hargaTiket(umur)</code> berdasarkan kategori:</p>\n<table style=\"border-collapse:collapse;width:100%;font-size:.9em;\">\n  <tr style=\"background:#1a1a2e;color:white;\"><th style=\"padding:7px;\">Kategori</th><th style=\"padding:7px;\">Usia</th><th style=\"padding:7px;\">Harga</th></tr>\n  <tr style=\"background:#f9f9f9;\"><td style=\"padding:7px;\">Anak-anak</td><td style=\"padding:7px;\">0ÔÇô12 tahun</td><td style=\"padding:7px;font-weight:bold;\">25000</td></tr>\n  <tr><td style=\"padding:7px;\">Remaja</td><td style=\"padding:7px;\">13ÔÇô17 tahun</td><td style=\"padding:7px;font-weight:bold;\">40000</td></tr>\n  <tr style=\"background:#f9f9f9;\"><td style=\"padding:7px;\">Dewasa</td><td style=\"padding:7px;\">ÔëÑ 18 tahun</td><td style=\"padding:7px;font-weight:bold;\">50000</td></tr>\n</table>','javascript','[{\"input\":\"8\",\"expected\":\"25000\"},{\"input\":\"15\",\"expected\":\"40000\"},{\"input\":\"25\",\"expected\":\"50000\"},{\"input\":\"12\",\"expected\":\"25000\"},{\"input\":\"18\",\"expected\":\"50000\"}]','// ­ƒÄ» Ujian 2.3: Sistem Tiket Bioskop\n// Mode UJIAN ÔÇö kerjakan mandiri!\n\nfunction hargaTiket(umur) {\n    // Gunakan if - else if - else\n    // Return angka (number), bukan string\n    \n}\n\n// Test\nconsole.log(hargaTiket(8));   // 25000\nconsole.log(hargaTiket(15));  // 40000\nconsole.log(hargaTiket(25));  // 50000\nconsole.log(hargaTiket(12));  // 25000\nconsole.log(hargaTiket(18));  // 50000\n','','',0,'exam','',1775624083,1775624083),(26,2,'­ƒÆ╗ Latihan 3.1 ÔÇö Data Siswa Array & Object','<p>Buat dan akses array serta object. <strong>Mode: Latihan</strong>.</p>',1,'<h3>­ƒôï Tugas</h3>\n<p>Lengkapi kode yang sudah ada:</p>\n<ol>\n  <li>Tampilkan elemen pertama array <code>mataPelajaran</code> dengan <code>console.log()</code></li>\n  <li>Tampilkan elemen terakhir array menggunakan <code>.length - 1</code></li>\n  <li>Tampilkan properti <code>kelas</code> dari object <code>profil</code></li>\n  <li>Ubah nilai <code>profil.nilai</code> menjadi <code>95</code> lalu tampilkan</li>\n</ol>','javascript','[{\"input\":\"\",\"expected\":\"Matematika\"},{\"input\":\"\",\"expected\":\"PPLG\"},{\"input\":\"\",\"expected\":\"11 PPLG\"},{\"input\":\"\",\"expected\":\"95\"}]','// ­ƒÄ» Latihan 3.1: Data Siswa\n\nlet mataPelajaran = [\"Matematika\", \"Bahasa Indonesia\", \"JavaScript\", \"PPLG\"];\n\nlet profil = {\n    nama : \"Andi Pratama\",\n    kelas: \"11 PPLG\",\n    nilai: 88\n};\n\n// 1. Tampilkan elemen PERTAMA array mataPelajaran\nconsole.log(mataPelajaran[0]);  // sudah benar\n\n// 2. Tampilkan elemen TERAKHIR (gunakan .length - 1)\nconsole.log(mataPelajaran[mataPelajaran.length - 1]);\n\n// 3. Tampilkan properti kelas dari profil\nconsole.log(profil.kelas);\n\n// 4. Ubah nilai menjadi 95, lalu tampilkan\nprofil.nilai = 95;\nconsole.log(profil.nilai);\n','','',0,'training','',1775624083,1775624083),(27,2,'­ƒÆ╗ Latihan 3.2 ÔÇö Manajemen Daftar Siswa','<p>Gunakan method array untuk mengelola daftar siswa. <strong>Mode: Latihan</strong>.</p>',1,'<h3>­ƒôï Tugas</h3>\n<p>Buatlah fungsi <code>tambahSiswa(arr, nama)</code> yang:</p>\n<ul>\n  <li>Menambahkan <code>nama</code> ke dalam array <code>arr</code> menggunakan <code>.push()</code></li>\n  <li>Mengembalikan array setelah ditambahkan</li>\n</ul>\n<p>Lalu buat fungsi <code>hitungSiswa(arr)</code> yang mengembalikan jumlah elemen array.</p>','javascript','[{\"input\":\"[\\\"Andi\\\",\\\"Budi\\\"], \\\"Citra\\\"\",\"expected\":\"[\\\"Andi\\\",\\\"Budi\\\",\\\"Citra\\\"]\"},{\"input\":\"[\\\"Andi\\\",\\\"Budi\\\",\\\"Citra\\\"]\",\"expected\":\"3\"}]','// ­ƒÄ» Latihan 3.2: Manajemen Daftar Siswa\n\nfunction tambahSiswa(arr, nama) {\n    // Tambahkan nama ke arr menggunakan .push()\n    // Return: array setelah ditambahkan\n    \n}\n\nfunction hitungSiswa(arr) {\n    // Return: jumlah elemen array\n    \n}\n\n// Test\nlet daftar = [\"Andi\", \"Budi\"];\nlet baru = tambahSiswa(daftar, \"Citra\");\nconsole.log(JSON.stringify(baru));     // [\"Andi\",\"Budi\",\"Citra\"]\nconsole.log(hitungSiswa(baru));        // 3\n','','',0,'training','',1775624084,1775624084),(28,2,'­ƒÄ» Ujian 3.3 ÔÇö Inventaris Barang Sekolah (Mode Ujian)','<p><strong>Mode: Ujian Mandiri</strong> ÔÇö Buat sistem inventaris menggunakan Array of Objects.</p>',1,'<h3>­ƒôï Tugas Ujian</h3>\n<p>Buatlah fungsi <code>cariBarangRusak(inventaris)</code> yang:</p>\n<ul>\n  <li>Menerima array of objects dengan properti <code>namaBarang</code> dan <code>kondisi</code></li>\n  <li>Mengembalikan array nama barang (string) yang kondisinya <code>\"Rusak\"</code></li>\n</ul>\n<p>Contoh: dari data di bawah ÔåÆ return <code>[\"Meja\", \"PC\"]</code></p>','javascript','[{\"input\":\"data\",\"expected\":\"[\\\"Meja\\\",\\\"PC\\\"]\"}]','// ­ƒÄ» Ujian 3.3: Inventaris Barang Sekolah\n// Mode UJIAN ÔÇö kerjakan mandiri!\n\nfunction cariBarangRusak(inventaris) {\n    // Filter hanya yang kondisi === \"Rusak\"\n    // Return: array berisi nama-nama barang yang rusak\n    \n}\n\n// Test\nlet data = [\n    { namaBarang: \"Kursi\", kondisi: \"Baik\"  },\n    { namaBarang: \"Meja\",  kondisi: \"Rusak\" },\n    { namaBarang: \"Papan\", kondisi: \"Baik\"  },\n    { namaBarang: \"PC\",    kondisi: \"Rusak\" }\n];\n\nconsole.log(JSON.stringify(cariBarangRusak(data)));\n// [\"Meja\",\"PC\"]\n','','',0,'exam','',1775624084,1775624084),(29,2,'­ƒÆ╗ Latihan 4.1 ÔÇö Fungsi Sapa & Perkenalan','<p>Buat dan panggil fungsi dasar. <strong>Mode: Latihan</strong>.</p>',1,'<h3>­ƒôï Tugas</h3>\n<p>Buatlah fungsi <code>sapa(nama)</code> yang menerima satu parameter <code>nama</code> dan mengembalikan string:</p>\n<p><code>\"Halo, [nama]! Selamat belajar JavaScript.\"</code></p>\n<p>Contoh: <code>sapa(\"Andi\")</code> ÔåÆ <code>\"Halo, Andi! Selamat belajar JavaScript.\"</code></p>','javascript','[{\"input\":\"Andi\",\"expected\":\"Halo, Andi! Selamat belajar JavaScript.\"},{\"input\":\"Budi\",\"expected\":\"Halo, Budi! Selamat belajar JavaScript.\"},{\"input\":\"Citra\",\"expected\":\"Halo, Citra! Selamat belajar JavaScript.\"}]','// ­ƒÄ» Latihan 4.1: Fungsi Sapa\n\nfunction sapa(nama) {\n    // Return: \"Halo, [nama]! Selamat belajar JavaScript.\"\n    \n}\n\n// Test ÔÇö panggil fungsi\nconsole.log(sapa(\"Andi\"));     // \"Halo, Andi! Selamat belajar JavaScript.\"\nconsole.log(sapa(\"Budi\"));     // \"Halo, Budi! Selamat belajar JavaScript.\"\nconsole.log(sapa(\"Citra\"));    // \"Halo, Citra! Selamat belajar JavaScript.\"\n','','',0,'training','',1775624084,1775624084),(30,2,'­ƒÆ╗ Latihan 4.2 ÔÇö Fungsi Cek & Hitung','<p>Implementasikan fungsi dengan parameter dan return value. <strong>Mode: Latihan</strong>.</p>',1,'<h3>­ƒôï Tugas</h3>\n<p>Buatlah dua fungsi:</p>\n<ol>\n  <li><code>cekGenap(n)</code> ÔåÆ return <code>true</code> jika <code>n</code> genap, <code>false</code> jika ganjil</li>\n  <li><code>hitungLuasPersegiPanjang(panjang, lebar)</code> ÔåÆ return luas (panjang ├ù lebar)</li>\n</ol>','javascript','[{\"input\":\"4\",\"expected\":\"true\"},{\"input\":\"7\",\"expected\":\"false\"},{\"input\":\"10, 5\",\"expected\":\"50\"},{\"input\":\"8, 3\",\"expected\":\"24\"}]','// ­ƒÄ» Latihan 4.2: Fungsi dengan Parameter & Return\n\nfunction cekGenap(n) {\n    // Return true jika n genap, false jika ganjil\n    \n}\n\nfunction hitungLuasPersegiPanjang(panjang, lebar) {\n    // Return hasil perkalian panjang dan lebar\n    \n}\n\n// Test\nconsole.log(cekGenap(4));                        // true\nconsole.log(cekGenap(7));                        // false\nconsole.log(hitungLuasPersegiPanjang(10, 5));    // 50\nconsole.log(hitungLuasPersegiPanjang(8, 3));     // 24\n','','',0,'training','',1775624085,1775624085),(31,2,'­ƒÄ» Ujian 4.3 ÔÇö Sistem Konversi Suhu (Mode Ujian)','<p><strong>Mode: Ujian Mandiri</strong> ÔÇö Buat fungsi konversi suhu menggunakan arrow function.</p>',1,'<h3>­ƒôï Tugas Ujian</h3>\n<p>Buatlah dua <strong>arrow function</strong>:</p>\n<ol>\n  <li><code>keFahrenheit(celsius)</code> ÔåÆ konversi Celsius ke Fahrenheit, rumus: <code>(C ├ù 9/5) + 32</code></li>\n  <li><code>keReamur(celsius)</code> ÔåÆ konversi Celsius ke Reamur, rumus: <code>C ├ù 4/5</code></li>\n</ol>\n<p>Gunakan sintaks arrow function!</p>','javascript','[{\"input\":\"0\",\"expected\":\"32\"},{\"input\":\"100\",\"expected\":\"212\"},{\"input\":\"100\",\"expected\":\"80\"},{\"input\":\"25\",\"expected\":\"20\"}]','// ­ƒÄ» Ujian 4.3: Konversi Suhu\n// Mode UJIAN ÔÇö gunakan arrow function!\n\n// 1. Arrow function Celsius ke Fahrenheit: (C ├ù 9/5) + 32\nconst keFahrenheit = // tulis di sini\n\n// 2. Arrow function Celsius ke Reamur: C ├ù 4/5\nconst keReamur = // tulis di sini\n\n// Test\nconsole.log(keFahrenheit(0));     // 32\nconsole.log(keFahrenheit(100));   // 212\nconsole.log(keReamur(100));       // 80\nconsole.log(keReamur(25));        // 20\n','','',0,'exam','',1775624085,1775624085),(32,2,'­ƒÆ╗ Latihan 5.1 ÔÇö Ubah Konten Halaman','<p>Ubah elemen HTML menggunakan getElementById. <strong>Mode: Latihan</strong>.</p>',1,'<h3>­ƒôï Tugas</h3>\n<p>Gunakan JavaScript untuk memanipulasi halaman di sebelah kanan:</p>\n<ol>\n  <li>Ubah teks <code>#judul</code> menjadi <code>\"Selamat Datang\"</code></li>\n  <li>Ubah teks <code>#deskripsi</code> menjadi <code>\"Belajar DOM JavaScript\"</code></li>\n  <li>Ubah warna teks <code>#warna</code> menjadi <code>\"blue\"</code></li>\n  <li>Tampilkan ke <code>#output</code> teks <code>\"DOM berhasil dimanipulasi!\"</code></li>\n</ol>','javascript','[{\"input\":\"\",\"expected\":\"Selamat Datang\"},{\"input\":\"\",\"expected\":\"DOM berhasil dimanipulasi!\"}]','// ­ƒÄ» Latihan 5.1: Ubah Konten DOM\n\n// 1. Pilih elemen berdasarkan ID dan ubah innerText-nya\ndocument.getElementById(\"judul\").innerText = \"Selamat Datang\";\n\n// 2. Ubah deskripsi\ndocument.getElementById(\"deskripsi\").innerText = \"Belajar DOM JavaScript\";\n\n// 3. Ubah warna teks #warna menjadi blue\ndocument.getElementById(\"warna\").style.color = \"blue\";\n\n// 4. Tampilkan pesan di #output\ndocument.getElementById(\"output\").innerText = \"DOM berhasil dimanipulasi!\";\n\n// Konfirmasi di console\nconsole.log(document.getElementById(\"judul\").innerText);\nconsole.log(document.getElementById(\"output\").innerText);\n','<div id=\"konten\">\n  <h2 id=\"judul\">Judul Asli</h2>\n  <p id=\"deskripsi\">Ini deskripsi awal.</p>\n  <p id=\"warna\" style=\"color:black;\">Teks berwarna</p>\n  <p id=\"output\">Menunggu...</p>\n</div>','body { font-family: Arial; padding: 15px; }\n#judul { color: #1a1a2e; }',0,'training','',1775624086,1775624086),(33,2,'­ƒÆ╗ Latihan 5.2 ÔÇö Tombol Interaktif','<p>Buat halaman interaktif dengan event handler. <strong>Mode: Latihan</strong>.</p>',1,'<h3>­ƒôï Tugas</h3>\n<p>Tambahkan event handler untuk tombol-tombol yang ada:</p>\n<ol>\n  <li><strong>Tombol \"Ubah Warna Latar\"</strong>: saat diklik, ubah <code>document.body.style.backgroundColor</code> menjadi <code>\"lightyellow\"</code>, tampilkan <code>\"Warna berubah!\"</code> di <code>#pesan</code></li>\n  <li><strong>Tombol \"Reset\"</strong>: kembalikan warna latar ke <code>\"\"</code> (kosong), tampilkan <code>\"Reset berhasil\"</code> di <code>#pesan</code></li>\n  <li><strong>Tombol \"Sapa\"</strong>: baca nilai dari <code>#inputNama</code>, tampilkan <code>\"Halo, [nama]!\"</code> di <code>#hasil</code></li>\n</ol>','javascript','[{\"input\":\"\",\"expected\":\"Event listeners terpasang!\"}]','// ­ƒÄ» Latihan 5.2: Event Handling\n\n// 1. Tombol Ubah Warna Latar\ndocument.getElementById(\"btnUbah\").addEventListener(\"click\", () => {\n    document.body.style.backgroundColor = \"lightyellow\";\n    document.getElementById(\"pesan\").innerText = \"Warna berubah!\";\n});\n\n// 2. Tombol Reset\ndocument.getElementById(\"btnReset\").addEventListener(\"click\", () => {\n    document.body.style.backgroundColor = \"\";\n    document.getElementById(\"pesan\").innerText = \"Reset berhasil\";\n});\n\n// 3. Tombol Sapa ÔÇö baca input, tampilkan sapaan\ndocument.getElementById(\"btnSapa\").addEventListener(\"click\", () => {\n    let nama = document.getElementById(\"inputNama\").value;\n    document.getElementById(\"hasil\").innerText = `Halo, ${nama}!`;\n});\n\nconsole.log(\"Event listeners terpasang!\");\n','<div style=\"padding:10px;\">\n  <h3 id=\"judul\">Halaman Interaktif</h3>\n  <button id=\"btnUbah\">Ubah Warna Latar</button>\n  <button id=\"btnReset\" style=\"margin-left:8px;\">Reset</button>\n  <p id=\"pesan\">Klik tombol di atas!</p>\n  <input id=\"inputNama\" type=\"text\" placeholder=\"Masukkan nama...\" style=\"padding:6px;margin-top:8px;\">\n  <button id=\"btnSapa\" style=\"margin-left:8px;\">Sapa</button>\n  <p id=\"hasil\"></p>\n</div>','body { font-family: Arial; } button { padding: 8px 14px; cursor: pointer; border: none; background: #2196F3; color: white; border-radius: 4px; } button:hover { background: #1976D2; }',0,'training','',1775624086,1775624086),(34,2,'­ƒÄ» Ujian 5.3 ÔÇö Aplikasi Pencatat Nama Tamu (Mode Ujian)','<p><strong>Mode: Ujian Mandiri</strong> ÔÇö Buat aplikasi pencatat nama tamu yang lengkap.</p>',1,'<h3>­ƒôï Tugas Ujian Akhir</h3>\n<p>Buat aplikasi pencatat nama tamu yang berfungsi penuh:</p>\n<ol>\n  <li><strong>Tombol \"Tambah\"</strong>: baca nilai <code>#inputTamu</code>, buat elemen <code>&lt;li&gt;</code> baru berisi nama tamu, tambahkan ke <code>#listTamu</code>, kosongkan input, update jumlah tamu di <code>#jumlah</code></li>\n  <li><strong>Tombol \"Hapus Terakhir\"</strong>: hapus elemen li terakhir dari daftar, update jumlah tamu</li>\n  <li>Gunakan <strong>innerText</strong> (bukan innerHTML) untuk keamanan</li>\n  <li>Validasi: jangan tambah jika input kosong</li>\n</ol>','javascript','[{\"input\":\"\",\"expected\":\"Aplikasi siap!\"}]','// ­ƒÄ» Ujian 5.3: Aplikasi Pencatat Nama Tamu\n// Mode UJIAN ÔÇö kerjakan mandiri!\n\nlet jumlahTamu = 0;\n\nfunction updateJumlah() {\n    document.getElementById(\"jumlah\").innerText = \"Jumlah tamu: \" + jumlahTamu;\n}\n\n// Tombol Tambah\ndocument.getElementById(\"btnTambah\").addEventListener(\"click\", () => {\n    let nama = document.getElementById(\"inputTamu\").value.trim();\n    \n    // Validasi: jangan tambah jika kosong\n    if (nama === \"\") return;\n    \n    // Tulis kode untuk:\n    // 1. Buat elemen li baru\n    // 2. Set innerText-nya dengan nama tamu\n    // 3. Append ke #listTamu\n    // 4. Kosongkan input\n    // 5. Tambah jumlahTamu dan update tampilan\n    \n});\n\n// Tombol Hapus Terakhir\ndocument.getElementById(\"btnHapus\").addEventListener(\"click\", () => {\n    let ul = document.getElementById(\"listTamu\");\n    // Tulis kode untuk:\n    // 1. Cek apakah ada elemen (ul.lastChild)\n    // 2. Hapus elemen terakhir\n    // 3. Kurangi jumlahTamu dan update tampilan\n    \n});\n\nupdateJumlah();\nconsole.log(\"Aplikasi siap!\");\n','<div id=\"app\" style=\"padding:10px;\">\n  <h3>­ƒôï Catatan Tamu</h3>\n  <div style=\"display:flex;gap:8px;margin-bottom:10px;\">\n    <input id=\"inputTamu\" type=\"text\" placeholder=\"Nama tamu...\" style=\"flex:1;padding:8px;border:1px solid #ddd;border-radius:4px;\">\n    <button id=\"btnTambah\" style=\"padding:8px 14px;background:#4CAF50;color:white;border:none;border-radius:4px;cursor:pointer;\">Tambah</button>\n    <button id=\"btnHapus\" style=\"padding:8px 14px;background:#f44336;color:white;border:none;border-radius:4px;cursor:pointer;\">Hapus Terakhir</button>\n  </div>\n  <ul id=\"listTamu\" style=\"list-style:none;padding:0;\"></ul>\n  <p id=\"jumlah\" style=\"color:#666;font-size:.9em;\">Jumlah tamu: 0</p>\n</div>','body { font-family: Arial; } #listTamu li { padding: 8px; margin: 4px 0; background: #f5f5f5; border-radius: 4px; border-left: 3px solid #2196F3; }',0,'exam','',1775624087,1775624087);
